package initdb

// pgProcBKIAttrs are the scalar pg_proc columns PostgreSQL 18.3's pg_proc.dat
// gives a built-in function (pgProcBKIAttrsByOID, generated by
// scripts/gen-pg-proc-attrs.py). pgProcRow overlays them on goopg's seed for
// the bootstrap heap a PostgreSQL node reads. goopg's seed table had defaulted
// most of them — 2455 functions were VOLATILE where PG has IMMUTABLE or STABLE,
// which on a PG node rejects those functions in index expressions and disables
// constant folding (M0149-0001g slice 15).
type pgProcBKIAttrs struct {
	Cost, Rows        int64
	Variadic, Support uint32
	Kind              byte
	SecDef, LeakProof bool
	Strict, RetSet    bool
	Volatile          byte
	Parallel          byte
	Bin               string // probin; "" = NULL
}
